begin;
create table if not exists public.usuarios(id uuid primary key references auth.users(id) on delete cascade, nome text not null, role text not null check(role in ('master','admin','funcionario')), ativo boolean not null default true);
create table if not exists public.produtos(id uuid primary key default gen_random_uuid(),nome text not null,descricao text,categoria text,marca text,preco_venda numeric(12,2) not null check(preco_venda>0));
create table if not exists public.variacoes_produto(id uuid primary key default gen_random_uuid(),produto_id uuid not null references public.produtos(id),tamanho text not null,cor text not null,codigo_barras text unique,estoque_atual integer not null default 0 check(estoque_atual>=0),estoque_minimo integer not null default 2 check(estoque_minimo>=0));
create table if not exists public.compras(id uuid primary key default gen_random_uuid(),fornecedor text,valor_total numeric(12,2) not null check(valor_total>0),status text not null);
create table if not exists public.vendas(id uuid primary key default gen_random_uuid(),usuario_id uuid not null references public.usuarios(id),valor_total numeric(12,2) not null check(valor_total>0),desconto numeric(12,2) not null default 0 check(desconto>=0 and desconto<=valor_total),forma_pagamento text not null check(forma_pagamento in ('pix','credito','debito','dinheiro')));
create table if not exists public.itens_compra(id uuid primary key default gen_random_uuid(),compra_id uuid not null references public.compras(id),variacao_id uuid not null references public.variacoes_produto(id),quantidade integer not null check(quantidade>0),custo_unitario numeric(12,2) not null check(custo_unitario>0));
create table if not exists public.itens_venda(id uuid primary key default gen_random_uuid(),venda_id uuid not null references public.vendas(id),variacao_id uuid not null references public.variacoes_produto(id),quantidade integer not null check(quantidade>0),preco_unitario_pago numeric(12,2) not null check(preco_unitario_pago>0));
create table if not exists public.fluxo_caixa(id uuid primary key default gen_random_uuid(),tipo text not null check(tipo in ('entrada','saida')),categoria text not null,valor numeric(12,2) not null check(valor>=0),descricao text,compra_id uuid references public.compras(id),venda_id uuid references public.vendas(id),data_competencia timestamptz not null default now());
commit;
